import{_ as l,l as o,o as e,c as s,v as t,p as d,x as r,d as n,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"ECDH 与 X25519","description":"","frontmatter":{"title":"ECDH 与 X25519","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ecdh-x25519.md","filePath":"cs/ecdh-x25519.md","lastUpdated":1789023840000}'),p={name:"cs/ecdh-x25519.md"};function E(A,a,D,u,_,m){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="ecdh-与-x25519" tabindex="-1">ECDH 与 X25519 <a class="header-anchor" href="#ecdh-与-x25519" aria-label="Permalink to &quot;ECDH 与 X25519&quot;">​</a></h1><div class="epigraph"><p>椭圆曲线 DH 用短得多的密钥达到与有限域 DH 同类的协商目标。X25519 把曲线、编码与钳位私钥收成一套难误用的合同，而不是「任意一条曲线都行」。</p><footer>—— Koblitz / Miller 椭圆曲线公钥；Bernstein, Curve25519；RFC 7748</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/rsa-attacks">RSA 攻击面</a>劝许多协议离开 RSA 封装。主干<a href="/cs/elliptic-curve-group">椭圆曲线</a>已有群直觉。缺口是<strong>ECDH 作为密钥协商</strong>：共享秘密是点的坐标派生，不是加密消息。X25519 是工程默认之一。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限域 DH 公钥大；ECDH 在合适曲线上密钥约 256 比特。小群、错误曲线、点不在曲线上，会把协商拉到弱群——本课只陈述必须校验或用蒙哥马利曲线避开一类检查。X25519：Curve25519、固定基、钳位。缺口是协商合同，不重推曲线方程。</p><h3 id="共享秘密还要-kdf" tabindex="-1">共享秘密还要 KDF <a class="header-anchor" href="#共享秘密还要-kdf" aria-label="Permalink to &quot;共享秘密还要 KDF&quot;">​</a></h3><p>ECDH 输出不是 AEAD 键。HKDF 更后；本课只要求「再派生」。</p><p><span class="marginnote">RFC 7748。TLS 1.3 的 x25519 是命名群。不要把任意自选曲线当同等安全。本课不给弱曲线参数的利用步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 DH：\\(g^a,g^b\\mapsto g^{ab}\\) 变成标量乘。陈述 X25519 的 32 字节编码。认证仍缺：无签名或预共享时，ECDH 对中间人成功。证书课已在主干；本进阶课后面信道单元再钉链验证细节。</p>',12)),(e(),d(c,null,{default:r(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%A0%87%E9%87%8F%20a%22%5D%20--%3E%20P%5B%22X25519%20%E5%85%AC%E9%92%A5%22%5D%0A%20%20B%5B%22%E5%AF%B9%E7%AB%AF%E5%85%AC%E9%92%A5%22%5D%20--%3E%20SS%5B%22%E5%85%B1%E4%BA%AB%E7%A7%98%E5%AF%86%22%5D%0A%20%20A%20--%3E%20SS%0A%20%20SS%20--%3E%20KDF%5B%22%E5%90%8E%E8%AF%BE%E6%B4%BE%E7%94%9F%20AEAD%20%E9%94%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前向保密来自临时标量。长期静态 ECDH 没有同样的遗忘性。实现必须用恒定时间标量乘；曲线选择把一类无效点问题收进规格。身份绑定仍是 PKI 或预共享。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 NIST 曲线清单。下一课 ECDSA/EdDSA：同一类群上的签名，与 DH 分工，密钥不要混用语义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RSA 封装之外，ECDH 做临时协商。</li><li>X25519 是难误用的 Curve25519 合同。</li><li>输出必须再 KDF；无认证则中间人成功。</li><li>下一课：同群上的签名 EdDSA/ECDSA。</li><li>出处：RFC 7748；Bernstein, Curve25519；对照 Diffie and Hellman, 1976。</li></ul>',8))])}const S=l(p,[["render",E]]);export{C as __pageData,S as default};
